    a, b = state[:2]
    old_g = state[2:]
    changed = list(old_g)
    changed[a - 1] = b
    return (old_g[a - 1], a, *changed)


def blank_matrix(n):
    return [[0 for _ in range(n)] for _ in range(n)]


def change_edge(matrix, a, b, delta):
    matrix[a - 1][b - 1] += delta
    if a != b:
